        pendingAmount: pendingAfterAbono,
        isLiquidado,
        kind: 'abono',
        reportedAtMs: abonoCreatedAt,
        liquidationTarget: liqAfterAbono,
        eventSnapshot: currentEvent,
        rosterParticipants: allParticipants,
        avisoUrl: privacyNoticePublicUrl,
